-- Day 6 widget hierarchy seed. Uses existing data_widgets and users_meta tables.
-- Widget E contains the first three fields and composes F and G as child widgets.
-- The Phone widget (F) is conditionally displayed based on Account Type (G).

INSERT INTO data_widgets (widget_name,widget_type,widget_data,widget_style,widget_class,widget_viewport,date_updated,updated_by,short_code,div_id,bootstrap_enabled,ssl_enabled,mobile_enabled,widget_html_element,widget_javascript,file_type,widget_settings,widget_values)
SELECT 'Day 6 formfieldF','Custom Widget','<div class="day6-form"><label for="d6_phone">Phone</label><input id="d6_phone" name="phone" type="tel" placeholder="Phone number"></div>','.day6-form{font-family:Arial,sans-serif;color:#222;max-width:680px;margin:auto;padding:12px}.day6-form label{display:block;margin:14px 0 6px;font-weight:600}.day6-form input,.day6-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;box-sizing:border-box}.day6-conditional{display:none}.day6-conditional.visible{display:block}','day6-component','front',DATE_FORMAT(NOW(),'%Y%m%d%H%i%s'),'Day 6','d6f00000000000000000000000000006','formfieldF',1,1,1,'div','','html','',''
WHERE NOT EXISTS (SELECT 1 FROM data_widgets WHERE widget_name='Day 6 formfieldF');

INSERT INTO data_widgets (widget_name,widget_type,widget_data,widget_style,widget_class,widget_viewport,date_updated,updated_by,short_code,div_id,bootstrap_enabled,ssl_enabled,mobile_enabled,widget_html_element,widget_javascript,file_type,widget_settings,widget_values)
SELECT 'Day 6 formfieldsG','Custom Widget','<div class="day6-form"><label for="d6_account">Account Type</label><select id="d6_account" name="account_type"><option value="">Select account type</option><option value="individual">Individual</option><option value="business">Business</option></select></div>','.day6-form{font-family:Arial,sans-serif;color:#222;max-width:680px;margin:auto;padding:12px}.day6-form label{display:block;margin:14px 0 6px;font-weight:600}.day6-form input,.day6-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;box-sizing:border-box}','day6-component','front',DATE_FORMAT(NOW(),'%Y%m%d%H%i%s'),'Day 6','d6g00000000000000000000000000007','formfieldsG',1,1,1,'div','','html','',''
WHERE NOT EXISTS (SELECT 1 FROM data_widgets WHERE widget_name='Day 6 formfieldsG');

INSERT INTO data_widgets (widget_name,widget_type,widget_data,widget_style,widget_class,widget_viewport,date_updated,updated_by,short_code,div_id,bootstrap_enabled,ssl_enabled,mobile_enabled,widget_html_element,widget_javascript,file_type,widget_settings,widget_values)
SELECT 'Day 6 formfieldE','Custom Widget','<div class="day6-form day6-hierarchy"><h2>Widget E – Hierarchical Form</h2><div class="row"><div><label for="d6_first">First Name</label><input id="d6_first" name="first_name" type="text" placeholder="First name"></div><div><label for="d6_last">Last Name</label><input id="d6_last" name="last_name" type="text" placeholder="Last name"></div></div><label for="d6_email">Email</label><input id="d6_email" name="email" type="email" placeholder="Email address">[widget=formfieldsG]<div id="d6_phone_wrap" class="day6-conditional">[widget=formfieldF]</div></div>','.day6-form{font-family:Arial,sans-serif;color:#222;max-width:680px;margin:auto;padding:20px}.day6-form h2{margin-top:0}.day6-form label{display:block;margin:14px 0 6px;font-weight:600}.day6-form input,.day6-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;box-sizing:border-box}.day6-form .row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.day6-conditional{display:none}.day6-conditional.visible{display:block}@media(max-width:600px){.day6-form .row{grid-template-columns:1fr}}','day6-component','front',DATE_FORMAT(NOW(),'%Y%m%d%H%i%s'),'Day 6','d6e00000000000000000000000000005','formfieldE',1,1,1,'div','(function(){const s=document.getElementById("d6_account"),p=document.getElementById("d6_phone_wrap");if(!s||!p)return;function sync(){p.classList.toggle("visible",s.value==="business");}s.addEventListener("change",sync);sync();})();','html','',''
WHERE NOT EXISTS (SELECT 1 FROM data_widgets WHERE widget_name='Day 6 formfieldE');

INSERT INTO users_meta (`database`,database_id,`key`,`value`,date_added)
SELECT 'data_widgets',w.widget_id,'widget_shortcode',a.alias,DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
FROM data_widgets w JOIN (SELECT 'Day 6 formfieldE' widget_name,'formfieldE' alias UNION ALL SELECT 'Day 6 formfieldF','formfieldF' UNION ALL SELECT 'Day 6 formfieldsG','formfieldsG') a ON a.widget_name=w.widget_name
WHERE NOT EXISTS (SELECT 1 FROM users_meta m WHERE m.`database`='data_widgets' AND m.database_id=w.widget_id AND m.`key`='widget_shortcode');
